<script setup>
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useLiveChatStore } from '@/stores/live-chat';
import ChatThread from '@/components/chat/ChatThread.vue';
const chat=useLiveChatStore(),route=useRoute(),router=useRouter(),busy=ref(false);
const labels={waiting:'Chờ hỗ trợ',active:'Đang xử lý',closed:'Đã kết thúc'};
const selectedId=computed(()=>typeof route.query.conversation==='string'?route.query.conversation:null);
const time=value=>value?new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'';
let timer;
watch([()=>chat.owner,()=>chat.staff,selectedId],()=>{if(chat.staff && chat.owner && selectedId.value && chat.selected?._id!==selectedId.value)void chat.view(selectedId.value);},{immediate:true});
watch([()=>chat.filters.filter,()=>chat.filters.keyword],()=>{clearTimeout(timer);timer=setTimeout(()=>{void chat.loadList();},250);});
watch(()=>chat.canManage,value=>{if(value)void chat.loadAgents();},{immediate:true});
function choose(con){router.replace({query:{conversation:con._id}});}
async function action(type,value){if(busy.value)return;busy.value=true;try{await chat.mutate(type,value);}finally{busy.value=false;}}
onBeforeUnmount(()=>{clearTimeout(timer);chat.typingState(false);});
</script>
<template><div class="live-chat-scope lc-admin-page"><div class="lc-page-heading"><div><p class="lc-eyebrow">Fresh Mart / Bộ phận hỗ trợ</p><h1>Chat hỗ trợ khách hàng</h1><p>Trao đổi trực tiếp, theo dõi lịch sử và phân công người phụ trách.</p></div><span class="lc-connection" :data-connection="chat.connection"><i class="fa-solid fa-circle" aria-hidden="true"></i>{{ chat.connection==='connected'?'Đã kết nối realtime':'Chưa kết nối' }}</span></div><div class="lc-inbox" :class="{'lc-inbox--selected':!!selectedId}"><aside class="lc-conversations" aria-label="Danh sách hội thoại"><div class="lc-inbox-title"><h2>Hộp thư hỗ trợ</h2><span v-if="chat.unread" class="lc-count">{{ chat.unread }} chưa đọc</span></div><label class="lc-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input v-model="chat.filters.keyword" placeholder="Tìm tên khách hàng" aria-label="Tìm khách hàng" maxlength="80" /></label><label class="lc-filter">Lọc hội thoại<select v-model="chat.filters.filter"><option value="all">Tất cả</option><option value="unread">Chưa đọc</option><option value="waiting">Đang chờ phản hồi</option><option value="active">Đang xử lý</option><option value="closed">Đã kết thúc</option></select></label><div class="lc-conversation-list"><p v-if="chat.listLoading && !chat.conversations.length" class="lc-empty" role="status">Đang tải hội thoại…</p><p v-else-if="!chat.conversations.length" class="lc-empty">Chưa có hội thoại phù hợp. Tin nhắn của khách sẽ xuất hiện tại đây.</p><button v-for="con in chat.conversations" :key="con._id" type="button" class="lc-conversation" :class="{'is-selected':chat.selected?._id===con._id,'is-unread':con.unreadCount>0}" @click="choose(con)"><span class="lc-avatar" aria-hidden="true"><img v-if="con.customer.avatar_url" :src="con.customer.avatar_url" alt="" loading="lazy" @error="$event.target.style.display='none'" />{{ con.customer.name.slice(0,1).toUpperCase() }}</span><span class="lc-conversation-copy"><span class="lc-conversation-top"><strong>{{ con.customer.name }}</strong><time :datetime="con.updatedAt">{{ time(con.updatedAt) }}</time></span><span class="lc-preview">{{ con.lastMessage?.senderKind==='support'?'Hỗ trợ: ':'' }}{{ con.lastMessage?.content || 'Chưa có tin nhắn' }}</span><span class="lc-conversation-bottom"><span class="lc-status" :data-status="con.status">{{ labels[con.status] }}</span><small>{{ con.assignedAdmin?.name || 'Chưa phân công' }}</small><b v-if="con.unreadCount" class="lc-unread">{{ con.unreadCount }}</b></span></span></button><button v-if="chat.nextCursor" type="button" class="lc-load-older" :disabled="chat.listLoading" @click="chat.loadList(true)">Tải thêm hội thoại</button></div><button type="button" class="lc-refresh" :disabled="chat.listLoading" @click="chat.sync"><i class="fa-solid fa-arrows-rotate" aria-hidden="true"></i> Làm mới hộp thư</button></aside><section class="lc-admin-thread" aria-label="Nội dung hội thoại"><template v-if="selectedId"><header class="lc-thread-header lc-admin-header"><button type="button" class="lc-back" aria-label="Về danh sách hội thoại" @click="router.replace({query:{}})"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i></button><span class="lc-avatar" aria-hidden="true"><img v-if="chat.selected?.customer.avatar_url" :src="chat.selected.customer.avatar_url" alt="" @error="$event.target.style.display='none'" />{{ chat.selected?.customer.name.slice(0,1) || '?' }}</span><div><h2>{{ chat.selected?.customer.name || 'Đang tải hội thoại…' }}</h2><p v-if="chat.selected">{{ labels[chat.selected.status] }} · {{ chat.selected.assignedAdmin?.name || 'Chưa phân công' }}</p></div><span class="lc-status" v-if="chat.selected && !chat.selected.customer.active">Tài khoản bị vô hiệu hóa</span></header><div v-if="chat.selected" class="lc-assignment"><button v-if="chat.canReply && !chat.selected.assignedAdminId && chat.selected.status!=='closed'" type="button" :disabled="busy" @click="action('assign',chat.owner)"><i class="fa-solid fa-hand" aria-hidden="true"></i> Nhận hội thoại</button><label v-if="chat.canManage && chat.selected.status!=='closed'">Phụ trách<select :value="chat.selected.assignedAdminId || ''" :disabled="busy" @change="action('assign',$event.target.value || null)"><option value="">Chưa phân công</option><option v-if="chat.selected.assignedAdminId && !chat.agents.some(agent=>agent._id===chat.selected.assignedAdminId)" :value="chat.selected.assignedAdminId" disabled>{{ chat.selected.assignedAdmin?.name }} (không khả dụng)</option><option v-for="agent in chat.agents" :key="agent._id" :value="agent._id">{{ agent.name }}</option></select></label><button v-if="chat.canManage || (chat.canReply && chat.selected.assignedAdminId===chat.owner)" type="button" :disabled="busy" @click="action('status',chat.selected.status==='closed'?'waiting':'closed')"><i :class="'fa-solid '+(chat.selected.status==='closed'?'fa-rotate-left':'fa-circle-check')" aria-hidden="true"></i>{{ chat.selected.status==='closed'?'Mở lại hội thoại':'Kết thúc hội thoại' }}</button></div><ChatThread /></template><div v-else class="lc-empty lc-inbox-empty"><span class="lc-empty-icon" aria-hidden="true"><i class="fa-regular fa-comments"></i></span><h2>Sẵn sàng hỗ trợ khách hàng</h2><p>Chọn hội thoại bên trái để xem lịch sử, nhận xử lý và trả lời.</p><small>Chưa đọc được tính riêng cho tài khoản của bạn.</small><p v-if="chat.error" class="lc-error" role="alert">{{ chat.error }}</p></div></section></div></div></template>
